Object.assign(globalThis.__FillBARSMedicalTemplates__, {"operationConsent": {"extension": "docx", "entries": [{"name": "[Content_Types].xml", "data": ""}, {"name": "_rels/.rels", "data": ""}, {"name": "word/document.xml", "data": ""}, {"name": "word/_rels/document.xml.rels", "data": ""}, {"name": "word/theme/theme1.xml", "data": ""}, {"name": "word/settings.xml", "data": ""}, {"name": "word/styles.xml", "data": ""}, {"name": "word/webSettings.xml", "data": ""}, {"name": "word/fontTable.xml", "data": ""}, {"name": "docProps/core.xml", "data": ""}, {"name": "docProps/app.xml", "data": ""}], "fields": ["fullName", "birthYear", "registeredAddress", "department", "operationName"], "preview": "<p style=\"text-align:justify\"></p><p style=\"\"><span style=\"\">            ФЕДЕРАЛЬНОЕ МЕДИКО-БИОЛОГИЧЕСКОЕ АГЕНТСТВО</span></p><p style=\"\"><span style=\"\">           ЦМСЧ/МСЧ/КБ/ИНСТИТУТ _______________________</span></p><p style=\"\"></p><p style=\"\"><span style=\"\"> </span></p><p style=\"\"><span style=\"\">              Информированное добровольное согласие</span></p><p style=\"\"><span style=\"\">      на оперативное вмешательство, в т.ч. переливание крови</span></p><p style=\"\"><span style=\"\">                         и ее компонентов</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">Я </span><span style=\"font-weight:bold\">{{fullName}}</span></p><p style=\"\"><span style=\"\">               (фамилия, имя, отчество - полностью)</span></p><p style=\"\"><span style=\"font-weight:bold\">{{birthYear}}</span><span style=\"\"> года рождения, проживающий(</span><span style=\"\">ая</span><span style=\"\">) по адресу: </span><span style=\"font-weight:bold\">{{registeredAddress}}</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">┌────────────────────────────────────────────────────────────────┐</span></p><p style=\"\"><span style=\"\">│Этот  раздел  бланка  заполняется  только  на  лиц, не достигших│</span></p><p style=\"\"><span style=\"\">│возраста 15 лет, или недееспособных граждан: Я, паспорт: ______,│</span></p><p style=\"\"><span style=\"\">│выдан: _________________________________________________________│</span></p><p style=\"\"><span style=\"\">│являюсь  законным   представителем  (мать,   отец,  усыновитель,│</span></p><p style=\"\"><span style=\"\">│опекун,    попечитель)    ребенка    или    лица,    признанного│</span></p><p style=\"\"><span style=\"\">│недееспособным: ________________________________________________│</span></p><p style=\"\"><span style=\"\">│                (Ф.И.О. ребенка или недееспособного гражданина -│</span></p><p style=\"\"><span style=\"\">│                            полностью, год рождения)            │</span></p><p style=\"\"><span style=\"\">└────────────────────────────────────────────────────────────────┘</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">находясь на лечении  (обследовании,  родоразрешении)  в  отделении</span></p><p style=\"\"><span style=\"font-weight:bold\">{{department}}</span></p><p style=\"\"><span style=\"\">                (название отделения, номер палаты)</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">добровольно даю свое согласие на проведение мне (представляемому):</span></p><p style=\"\"><span style=\"\">операции: </span><span style=\"font-weight:bold\">{{operationName}}</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">              (название медицинского вмешательства)</span></p><p style=\"\"><span style=\"\">и прошу персонал медицинского учреждения о ее проведении.</span></p><p style=\"\"><span style=\"\">Подтверждаю,   что   я   ознакомлен   (ознакомлена)  с  характером</span></p><p style=\"\"><span style=\"\">предстоящей мне (представляемому) операции. Мне  разъяснены,  и  я</span></p><p style=\"\"><span style=\"\">понимаю особенности и ход предстоящего оперативного лечения.</span></p><p style=\"\"><span style=\"\">-  Мне  разъяснено  и  я  осознаю,  что  во  время  операции могут</span></p><p style=\"\"><span style=\"\">возникнуть  непредвиденные  обстоятельства  и  осложнения. В таком</span></p><p style=\"\"><span style=\"\">случае  я  согласен  (согласна) на то, что ход операции может быть</span></p><p style=\"\"><span style=\"\">изменен врачами по их усмотрению.</span></p><p style=\"\"><span style=\"\">-  Я  предупрежден (предупреждена) о факторах риска и понимаю, что</span></p><p style=\"\"><span style=\"\">проведение  операции сопряжено с риском потери крови, возможностью</span></p><p style=\"\"><span style=\"\">инфекционных  осложнений, нарушений со стороны сердечно-сосудистой</span></p><p style=\"\"><span style=\"\">и  других  систем  жизнедеятельности  организма, непреднамеренного</span></p><p style=\"\"><span style=\"\">причинения вреда здоровью и даже неблагоприятного исхода.</span></p><p style=\"\"><span style=\"\">-  Я  предупрежден  (предупреждена),  что  в  ряде  случаев  могут</span></p><p style=\"\"><span style=\"\">потребоваться  повторные  операции,  в  т.ч.  в связи с возможными</span></p><p style=\"\"><span style=\"\">послеоперационными   осложнениями   или  с  особенностями  течения</span></p><p style=\"\"><span style=\"\">заболевания, и даю свое согласие на это.</span></p><p style=\"\"><span style=\"\">-  Я  поставил (поставила) в известность врача обо всех проблемах,</span></p><p style=\"\"><span style=\"\">связанных  со  здоровьем, в том числе об аллергических проявлениях</span></p><p style=\"\"><span style=\"\">или  индивидуальной  непереносимости лекарственных препаратов, обо</span></p><p style=\"\"><span style=\"\">всех  перенесенных  мною (представляемым) и известных мне травмах,</span></p><p style=\"\"><span style=\"\">операциях,   заболеваниях,   в   т.ч.  носительстве  ВИЧ-инфекции,</span></p><p style=\"\"><span style=\"\">вирусных  гепатитах,  туберкулезе, инфекциях, передаваемых половым</span></p><p style=\"\"><span style=\"\">путем,  об  экологических  и производственных факторах физической,</span></p><p style=\"\"><span style=\"\">химической  или  биологической  природы,  воздействующих  на  меня</span></p><p style=\"\"><span style=\"\">(представляемого)    во   время   жизнедеятельности,   принимаемых</span></p><p style=\"\"><span style=\"\">лекарственных  средствах, проводившихся ранее переливаниях крови и</span></p><p style=\"\"><span style=\"\">ее   компонентов.   Сообщил   (сообщила)   правдивые   сведения  о</span></p><p style=\"\"><span style=\"\">наследственности,  а также об употреблении алкоголя, наркотических</span></p><p style=\"\"><span style=\"\">и токсических средств.</span></p><p style=\"\"><span style=\"\">-  Я  знаю, что во время операции возможна потеря крови и ________</span></p><p style=\"\"><span style=\"\">даю согласие на переливание донорской или </span><span style=\"\">ауто</span><span style=\"\"> (собственной) крови</span></p><p style=\"\"><span style=\"\">и ее компонентов.</span></p><p style=\"\"><span style=\"\">- Я _______________ согласен (согласна) на запись хода операции на</span></p><p style=\"\"><span style=\"\">информационные   носители   и  демонстрацию  лицам  с  медицинским</span></p><p style=\"\"><span style=\"\">образованием исключительно в медицинских,  научных  или  обучающих</span></p><p style=\"\"><span style=\"\">целях с учетом сохранения врачебной тайны.</span></p><p style=\"\"><span style=\"\">-  Мне  была  предоставлена  возможность  задать вопросы о степени</span></p><p style=\"\"><span style=\"\">риска  и  пользе  оперативного  вмешательства,  в т.ч. переливаний</span></p><p style=\"\"><span style=\"\">донорской или </span><span style=\"\">ауто</span><span style=\"\"> (собственной) крови и/или ее компонентов и врач</span></p><p style=\"\"><span style=\"\">дал понятные мне исчерпывающие ответы.</span></p><p style=\"\"><span style=\"\">- Я ознакомлен  (ознакомлена)  и  согласен   (согласна)  со  всеми</span></p><p style=\"\"><span style=\"\">пунктами настоящего  документа, положения которого мне разъяснены,</span></p><p style=\"\"><span style=\"\">мною поняты и добровольно даю свое согласие на ___________________</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">                                                             ----</span></p><p style=\"\"><span style=\"\">&quot;__&quot; ___________ 20__ года     </span><span style=\"\">  Подпись пациента/законного </span></p><p style=\"\"><span style=\"\">                                 представителя               ----</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">Расписался в моем присутствии:                               ----</span></p><p style=\"\"><span style=\"\">Врач ___________________________________________ (подпись) </span></p><p style=\"\"><span style=\"\">              (должность, И.О. Фамилия)                      ----                     </span></p><p style=\"\"></p><p style=\"\"><span style=\"\">ПРИМЕЧАНИЕ:</span></p><p style=\"\"><span style=\"\">    Согласие  на  медицинское  вмешательство  в  отношении лиц, не</span></p><p style=\"\"><span style=\"\">достигших  возраста  15 лет, и граждан, признанных в установленном</span></p><p style=\"\"><span style=\"\">законом  порядке  недееспособными,  дают их законные представители</span></p><p style=\"\"><span style=\"\">(родители,   усыновители,  опекуны  или  попечители)  с  указанием</span></p><p style=\"\"><span style=\"\">Ф.И.О.,  паспортных  данных, родственных отношений после сообщения</span></p><p style=\"\"><span style=\"\">им  сведений  о результатах обследования, наличии заболевания, его</span></p><p style=\"\"><span style=\"\">диагнозе  и  прогнозе,  методах  лечения,  связанном с ними риске,</span></p><p style=\"\"><span style=\"\">возможных  вариантах медицинского вмешательства, их последствиях и</span></p><p style=\"\"><span style=\"\">результатах проведенного лечения.</span></p><p style=\"\"><span style=\"\">    При  отсутствии  законных представителей решение о медицинском</span></p><p style=\"\"><span style=\"\">вмешательстве  принимает  консилиум,  а  при невозможности собрать</span></p><p style=\"\"><span style=\"\">консилиум  - непосредственно лечащий (дежурный) врач с последующим</span></p><p style=\"\"><span style=\"\">уведомлением  главного врача/начальника ЦМСЧ/МСЧ/КБ/Института, а в</span></p><p style=\"\"><span style=\"\">выходные,   праздничные   дни,   вечернее   и   ночное   время   -</span></p><p style=\"\"><span style=\"\">ответственного дежурного врача и законных представителей.</span></p><p style=\"\"><span style=\"\">    В   случаях,  когда  состояние  гражданина  не  позволяет  ему</span></p><p style=\"\"><span style=\"\">выразить  свою волю, а медицинское вмешательство неотложно, вопрос</span></p><p style=\"\"><span style=\"\">о  его  проведении  в интересах гражданина решает консилиум, а при</span></p><p style=\"\"><span style=\"\">невозможности   собрать   консилиум   -   непосредственно  лечащий</span></p><p style=\"\"><span style=\"\">(дежурный)    врач    с    последующим    уведомлением    главного</span></p><p style=\"\"><span style=\"\">врача/начальника ЦМСЧ/МСЧ/КБ/Института,  а в выходные, праздничные</span></p><p style=\"\"><span style=\"\">дни, вечернее и ночное время - ответственного дежурного врача.</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">Дополнительная информация:</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"><span style=\"\">__________________________________________________________________</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">                                                             ----</span></p><p style=\"\"><span style=\"\">&quot;__&quot; ___________ 20__ года       Подпись пациента/законного </span></p><p style=\"\"><span style=\"\">                                 представителя               ----</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">Расписался в моем присутствии:                               ----</span></p><p style=\"\"><span style=\"\">Врач ___________________________________________ (подпись)  </span></p><p style=\"\"><span style=\"\">              (должность, И.О. Фамилия)                      ----</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">Консилиум врачей в составе:</span></p><p style=\"\"><span style=\"\">Должность, Ф.И.О. и подпись ______________________________________</span></p><p style=\"\"><span style=\"\">Должность, Ф.И.О. и подпись ______________________________________</span></p><p style=\"\"><span style=\"\">Должность, Ф.И.О. и подпись ______________________________________</span></p><p style=\"\"></p><p style=\"\"><span style=\"\">&quot;__&quot; ___________ 20__ года</span></p>", "checkboxes": {}}, "anesthesiaConsent": {"extension": "docx", "entries": [{"name": "[Content_Types].xml", "data": ""}, {"name": "_rels/.rels", "data": ""}, {"name": "word/document.xml", "data": ""}, {"name": "word/_rels/document.xml.rels", "data": ""}, {"name": "word/footnotes.xml", "data": ""}, {"name": "word/endnotes.xml", "data": ""}, {"name": "word/header1.xml", "data": ""}, {"name": "word/theme/theme1.xml", "data": ""}, {"name": "word/settings.xml", "data": ""}, {"name": "word/styles.xml", "data": ""}, {"name": "word/webSettings.xml", "data": ""}, {"name": "word/fontTable.xml", "data": ""}, {"name": "docProps/core.xml", "data": ""}, {"name": "docProps/app.xml", "data": ""}], "fields": ["fullName", "birthYear", "address", "department"], "preview": "<p style=\"\"><span style=\"font-size:8.0pt\">Приложение № 2</span><span style=\"font-size:8.0pt\"><br>УТВЕРЖДЕНО</span><span style=\"font-size:8.0pt\"><br>Приказом ФМБА России</span><span style=\"font-size:8.0pt\"><br>от 30.03.2007 № 88</span></p><p style=\"text-align:center;margin-top:12.0pt\"><span style=\"font-weight:bold;font-size:13.5pt\">ФЕДЕРАЛЬНОЕ МЕДИКО-БИОЛОГИЧЕСКОЕ АГЕНТСТВО</span></p><p style=\"\"><span style=\"font-size:13.5pt\">ЦМСЧ/МСЧ/КБ/ИНСТИТУТ  </span></p><p style=\"\"></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:13.5pt\">Информированное добровольное согласие</span><span style=\"font-weight:bold;font-size:13.5pt\"><br>на анестезиологическое обеспечение медицинского вмешательства</span></p><p style=\"margin-top:12.0pt\"><span style=\"font-size:11.5pt\">Я </span><span style=\"font-weight:bold;font-size:11.5pt\">{{fullName}}</span></p><p style=\"text-align:center\"><span style=\"font-size:8.0pt\">(фамилия, имя, отчество – полностью)</span></p><table><tr><td><p style=\"text-align:center\"><span style=\"font-weight:bold\">{{birthYear}}</span></p></td><td><p style=\"text-align:center\"><span style=\"font-size:11.5pt\">года рождения, проживающий(ая) по адресу:</span></p></td><td><p style=\"\"><span style=\"font-weight:bold\">{{address}}</span></p></td></tr></table><p style=\"\"></p><p style=\"margin-bottom:12.0pt\"></p><table><tr><td><p style=\"text-align:justify\"><span style=\"font-weight:bold;font-size:10.5pt\">Этот раздел бланка заполняется только на лиц, не достигших возраста 15 лет, или недееспособных</span><span style=\"font-weight:bold;font-size:10.5pt\"><br></span></p></td></tr><tr><td><p style=\"\"><span style=\"font-weight:bold;font-size:10.5pt\">граждан:</span><span style=\"font-size:10.5pt\"> Я, паспорт:</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-size:10.5pt\">, выдан:</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"text-align:justify\"><span style=\"font-size:10.5pt\">являюсь законным представителем </span><span style=\"font-weight:bold;font-size:10.5pt\">(мать, отец, усыновитель, опекун, попечитель)</span><span style=\"font-size:10.5pt\"> ребенка или лица,</span><span style=\"font-size:10.5pt\"><br></span></p></td></tr><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">признанного недееспособным:</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:8.0pt\">(Ф.И.О. ребенка или недееспособного гражданина – полностью, год рождения)</span></p></td><td><p style=\"\"></p></td></tr></table><p style=\"margin-top:6.0pt\"><span style=\"font-size:9.5pt\">находясь на лечении (обследовании, родоразрешении) в отделении </span><span style=\"font-weight:bold;font-size:9.5pt\">{{department}}</span></p><p style=\"\"></p><p style=\"\"></p><p style=\"text-align:center\"><span style=\"font-size:8.0pt\">(название отделения, номер палаты)</span></p><p style=\"\"></p><p style=\"\"></p><p style=\"margin-top:3.0pt\"><span style=\"font-size:9.5pt\">Добровольно даю свое согласие на проведение мне (представляемому):  </span></p><p style=\"text-align:center;margin-top:3.0pt\"><span style=\"\">ТВВА</span><span style=\"\">            </span><span style=\"\">ТВВА + ИВЛ</span><span style=\"\">         Комбинированная анестезия       </span><span style=\"\">СМА</span><span style=\"\"> </span><span style=\"\">    </span><span style=\"\">Про</span><span style=\"\">воднико</span><span style=\"\">вая блокада</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:8.0pt\">(название вида обезболивания, возможность изменения анестезиологической тактики)</span></p><p style=\"text-align:justify;margin-top:6.0pt\"><span style=\"font-size:9.5pt\">- Я поставил (поставила) в известность врача обо всех проблемах, связанных со здоровьем, в том числе об аллергических проявлениях или индивидуальной непереносимости лекарственных препаратов, пищи, бытовой химии, пыльцы цветов; обо всех перенесенных мною (представляемым) и известных мне травмах, операциях, заболеваниях, анестезиологических пособиях; об экологических и производственных факторах физической, химической или биологической природы, воздействующих на меня (представляемого) во время жизнедеятельности, о принимаемых лекарственных средствах. Сообщил (сообщила) правдивые сведения о наследственности, употреблении алкоголя, наркотических и токсических средств;</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">- Я информирован (информирована) о целях, характере и неблагоприятных эффектах анестезиологического обеспечения медицинского вмешательства, а также о том, что предстоит мне (представляемому) делать во время его проведения;</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">- Я предупрежден (предупреждена) о факторах риска и понимаю, что проведение анестезиологического обеспечения медицинского вмешательства сопряжено с риском нарушений со стороны сердечно-сосудистой, нервной, дыхательной и других систем жизнедеятельности организма, непреднамеренного причинения вреда здоровью, и даже неблагоприятного исхода;</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">- Мне разъяснено и я осознаю, что во время анестезиологического пособия могут возникнуть непредвиденные обстоятельства и осложнения. В таком случае, я согласен (согласна) на то, что вид и тактика анестезиологического пособия может быть изменена врачами по их усмотрению;</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">- Я ознакомлен (ознакомлена) и согласен (согласна) со всеми пунктами настоящего документа, положения которого мне разъяснены, мною поняты и добровольно даю свое согласие на проведение анестезиологического обеспечения медицинского вмешательства в предложенном объеме.</span></p><p style=\"margin-top:12.0pt\"><span style=\"font-size:9.5pt\">О последствиях  </span><span style=\"font-size:9.5pt\">    </span><span style=\"font-size:9.5pt\">    </span><span style=\"font-size:9.5pt\">    </span><span style=\"font-size:9.5pt\">    </span><span style=\"font-size:9.5pt\">    предупрежден/а</span></p><p style=\"\"></p><p style=\"\"></p><p style=\"text-align:center\"><span style=\"font-size:8.0pt\">(возможных осложнениях при выполнении анестезии)</span></p><p style=\"\"><span style=\"font-size:9.5pt\">и связанных с ними риском информирован (информирована) врачом антестезиологом-реаниматором:</span></p><p style=\"\"></p><p style=\"text-align:center;margin-bottom:12.0pt\"><span style=\"font-size:8.0pt\">(фамилия, имя, отчество врача анастезиолога-реаниматора)</span></p><table><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">“</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-size:10.5pt\">”</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:right\"><span style=\"font-size:10.5pt\">20</span></p></td><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:10.5pt\">года. </span><span style=\"text-decoration:underline;font-size:10.5pt\">Подпись пациента/законного представителя</span></p></td><td><p style=\"\"><span style=\"font-weight:bold;font-size:10.5pt\">Х</span></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td></tr></table><p style=\"\"></p><table><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">Расписался в моем присутствии:</span></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">Врач</span></p></td><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:10.5pt\">(подпись)</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-weight:bold;font-size:10.5pt\">Х</span></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:8.5pt\">( И.О. Фамилия)</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr></table><p style=\"text-align:center;margin-top:3.0pt\"><span style=\"\"></span><span style=\"font-weight:bold;font-size:10.5pt\">СМОТРИТЕ ОБОРОТ БЛАНКА</span></p><p style=\"\"><span style=\"font-weight:bold;font-size:13.5pt\">ПРИМЕЧАНИЕ:</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">Согласие на анестезиологическое обеспечение медицинского вмешательства в отношении лиц, не достигших возраста 15 лет, и граждан, признанных в установленном законом порядке недееспособными, дают их законные представители (родители, усыновители, опекуны или попечители) с указанием Ф.И.О., паспортных данных, родственных отношений после сообщения им сведений о возможных вариантах медицинского вмешательства, их последствиях и результатах проведенного лечения с учетом состояния здоровья пациента.</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">При отсутствии законных представителей решение об анестезиологическом обеспечении медицинского вмешательства принимает консилиум, а при невозможности собрать консилиум – непосредственно анестезиолог-реаниматолог и лечащий (дежурный) врач с последующим уведомлением главного врача/начальника ЦМСЧ/МСЧ/КБ/Института, а в выходные, праздничные дни, вечернее и ночное время – ответственного дежурного врача и законных представителей.</span></p><p style=\"text-align:justify\"><span style=\"font-size:9.5pt\">В случаях, когда состояние гражданина не позволяет ему выразить свою волю, а медицинское вмешательство неотложно, вопрос об анестезиологическом обеспечении при проведении медицинского вмешательства в интересах гражданина решает консилиум, а при невозможности собрать консилиум – непосредственно врач анестезиолог-реаниматолог и лечащий (дежурный) врач с последующим уведомлением главного врача/начальника ЦМСЧ/МСЧ/КБ/Института, а в выходные, праздничные дни, вечернее и ночное время – ответственного дежурного врача.</span></p><p style=\"margin-top:12.0pt\"><span style=\"font-weight:bold;font-size:10.5pt\">Дополнительная информация:</span></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"\"></p><p style=\"margin-bottom:12.0pt\"></p><table><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">“</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-size:10.5pt\">”</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:right\"><span style=\"font-size:10.5pt\">20</span></p></td><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:10.5pt\">года. </span><span style=\"text-decoration:underline;font-size:10.5pt\">Подпись пациента/законного представителя</span></p></td><td><p style=\"\"><span style=\"font-weight:bold;font-size:10.5pt\">Х</span></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td></tr></table><p style=\"\"></p><table><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">Расписался в моем присутствии:</span></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"\"><span style=\"font-size:10.5pt\">Врач</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:10.5pt\">(подпись)</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-weight:bold;font-size:10.5pt\">Х</span></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"text-align:center\"><span style=\"font-size:8.5pt\">(Должность, И.О. Фамилия)</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr><tr><td><p style=\"\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"></p></td></tr></table><p style=\"margin-top:6.0pt\"><span style=\"font-weight:bold;font-size:11.5pt\">Консилиум врачей в составе:</span></p><p style=\"\"><span style=\"font-size:11.5pt\">Должность, Ф.И.О. и подпись  </span></p><p style=\"\"></p><p style=\"\"><span style=\"font-size:11.5pt\">Должность, Ф.И.О. и подпись  </span></p><p style=\"\"></p><p style=\"\"><span style=\"font-size:11.5pt\">Должность, Ф.И.О. и подпись  </span></p><p style=\"margin-bottom:12.0pt\"></p><table><tr><td><p style=\"\"><span style=\"font-size:11.5pt\">“</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"\"><span style=\"font-size:11.5pt\">”</span></p></td><td><p style=\"text-align:center\"></p></td><td><p style=\"text-align:right\"><span style=\"font-size:11.5pt\">20</span></p></td><td><p style=\"\"></p></td><td><p style=\"\"><span style=\"font-size:11.5pt\">года</span></p></td></tr></table><p style=\"\"></p>", "checkboxes": {}}});
